mapper.select:
select b.*, ifnull(u.user_name,"用户不存在") as userName from business_card b left join tb_user u on u.user_id = b.user_id
and u.user_name like concat("%",#{userName},"%")
and b.company_name like concat("%",#{companyName},"%")
and b.card_status = #{cardStatus}
and b.card_type = #{userType}
and b.real_name like concat("%",#{businessCard.realName},"%")
and b.industry_first_name like concat("%",#{industryFirstName},"%")
and b.audit_status = #{auditStatus}
order by b.create_time desc

SELECT * FROM business_card WHERE user_id = #{userId} AND audit_status = '1'
and card_type = #{cardType}
ORDER BY card_status DESC, create_time DESC

SELECT * FROM business_card

    1=1

       and user_id = #{userId}


        AND audit_status = #{auditStatus}


        AND card_Type = #{cardType}


ORDER BY
    card_status DESC,
    create_time DESC

mapper.update:
UPDATE business_card
SET used_quota = used_quota + #{num},
    quota = quota - #{num}
WHERE
    card_id = #{cardId}

mapper.select:
SELECT * FROM business_card

    1=1

        and user_id = #{userId}


        and parent_id = #{parentId}

SELECT ( @sortNum := @sortNum + 1 ) AS sortNum, b.card_id, b.card_avatar, b.card_type, b.real_name, b.company_name, b.company_position, b.popularity_value, b.user_id, (select count(*) from user_card_list ucl where ucl.card_id=b.card_id and ucl.user_id=#{userId}) as userCardListCount, (select m.status from message_info m where m.by_user_id=#{userId} and m.platform_id=b.card_id and m.type=1 and m.state=6) as messageStatus FROM business_card b, ( SELECT @sortNum := #{sortNum} ) AS sortNum
and b.industry_second_name = #{industrySecondName}
and b.company_province = #{companyProvince}
and b.company_city = #{companyCity}
and b.company_district = #{companyDistrict}
and b.card_status=1 and b.audit_status=1
ORDER BY b.popularity_value desc

SELECT
    count(*)
FROM
    business_card


        and card_type = #{cardType}


        and create_time BETWEEN #{startTime} and #{endTime}
